<template><section v-if="evidence.length" class="evidence"><h3>检测证据</h3><div class="grid"><article v-for="item in evidence" :key="item.id||item.file_name"><strong>{{item.file_name||'检测图片'}}</strong><div class="pair"><div v-if="item.input_url"><span>原图</span><el-image :src="item.input_url" fit="contain" :preview-src-list="[item.input_url]" preview-teleported/></div><div v-if="item.result_url"><span>标注图</span><el-image :src="item.result_url" fit="contain" :preview-src-list="[item.result_url]" preview-teleported/></div></div></article></div></section></template>
<script setup>import { computed } from 'vue';const props=defineProps({items:{type:Array,default:()=>[]},task:{type:Object,default:null}});const evidence=computed(()=>props.items.length?props.items.filter(i=>i.input_url||i.result_url).slice(0,20):(props.task?.input_url||props.task?.result_url?[{id:'task',file_name:'检测输入',input_url:props.task.input_url,result_url:props.task.result_url}]:[]))</script>
<style lang="scss" scoped>.evidence{margin-top:18px}.evidence h3{color:$text-primary;font-size:15px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid article{padding:10px;border:1px solid $border-color;border-radius:$border-radius-md;background:$surface-color-soft}.grid article>strong{display:block;margin-bottom:8px;color:$text-primary;font-size:12px}.pair{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.pair span{display:block;margin-bottom:4px;color:$text-secondary;font-size:11px}.pair :deep(.el-image){width:100%;height:130px;border-radius:6px;background:#eef3f8}@media(max-width:620px){.grid{grid-template-columns:1fr}}</style>
